INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61596320', 61596320, 'analyze_legacy', 'Kementerian Agama', 'central', 'IAIN MANADO 426251', 'Pengadaan Jasa Satpam, Petugas Kebersihan dan Pengemudi  IAIN Manado', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Utara, Manado (Kota)', 1920000000, 'November 2025', 'APBN - PNBP (D)', 1, 1, '10 Bulan', 'Pekerjaan ini bertujuan untuk mendukung kelancaran operasional dan keamanan lingkungan kerja di seluruh area kampus IAIN Manado melalui penyediaan tenaga jasa keamanan (satpam), petugas kebersihan (cleaning service), dan pengemudi (driver) yang profesional, terampil, dan bertanggung jawab. Pekerjaan dilaksanakan selama 10 (sepuluh) bulan dalam satu tahun anggaran, dengan sistem pembayaran berdasarkan hasil kerja dan absensi tenaga setiap bulan. Penyedia wajib menempatkan tenaga sesuai kontrak dan memastikan keberlangsungan layanan tanpa gangguan.', 'a. Tenaga Satpam: Memiliki sertifikat pelatihan dasar keamanan (Gada Pratama). Menguasai prosedur pengamanan kampus dan pelayanan publik. Ditempatkan di pos dan area strategis. b. Tenaga Kebersihan: Berpengalaman dalam pekerjaan cleaning service. Mampu menggunakan peralatan dan bahan pembersih dengan benar. Bertugas sesuai pembagian area dan jadwal kerja. c. Tenaga Pengemudi: Memiliki SIM A aktif dan pengalaman mengemudi minimal 2 tahun. Menguasai etika berkendara dan perawatan ringan kendaraan dinas.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1049);
