INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62306012', 62306012, 'analyze_legacy', 'Badan Narkotika Nasional', 'central', 'BADAN NARKOTIKA NASIONAL KABUPATEN CIAMIS', 'Belanja Tenaga kontrak alih daya (outsourcing)', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Ciamis (Kab.)', 201276000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 paket', '1. Tenaga Alih Daya Pramubakti ( 36, OB, @ 4123000 ); 2. Tenaga Alih Daya Pengemudi ( 12, OB, @ 4404000 );', '1. Spesifikasi Pramubakti minimal SMA/SMK sederajat untuk tugas umum (kebersihan, pelayanan, administrasi dasar seperti fotocopy, antar dokumen), dan untuk peran lebih spesifik seperti administrasi perkantoran atau operator komputer bisa D3/S1, dengan kualifikasi tambahan seperti sehat jasmani-rohani, berkelakuan baik, bisa bekerja tim, serta memiliki skill relevan (misal komputer). a. Spesifikasi Umum (SMA/SMK) - Pendidikan: Minimal SMA/SMK/Sederajat. - Usia: 19-50 tahun - Kewarganegaraan: Indonesia. - Pengalaman: Minimal 1 tahun - Kesehatan: Sehat jasmani dan rohani (dibuktikan surat sehat). - Kelengkapan Dokumen: KTP, SKCK, Surat Sehat, Surat Keterangan Bebas Narkoba. - Tugas : Menjaga kebersihan, kerapihan, pelayanan umum, fotocopy, pengantaran dokumen, membantu pekerjaan operasional harian. - Kualifikasi Tambahan: Sehat jasmani-rohani, berkelakuan baik, bersedia bekerja penuh waktu, bisa bekerja dalam tim. b. Spesifikasi untuk Tingkat Lebih Tinggi (D3/S1) - Pendidikan: D3 atau S1 (Sarjana). - Usia: 22-50 tahun - Kewarganegaraan: Indonesia. - Pengalaman: Minimal 1 tahun - Kesehatan: Sehat jasmani dan rohani (dibuktikan surat sehat). - Kelengkapan Dokumen: KTP, SKCK, Surat Sehat, Surat Keterangan Bebas Narkoba. - Tugas: Peran lebih spesifik seperti Pramubakti Administrasi (operator komputer, penata usaha, keuangan, kehumasan). - Kualifikasi Tambahan: Kemampuan komputer (operator komputer), keahlian khusus sesuai bidang (misal: IT, Akuntansi, Hukum, Manajemen). 2. Spesifikasi Pengemudi : - Pendidikan: Minimal SMA/Sederajat. - Dokumen: Memiliki SIM A dan berlaku, KTP, SKCK, Surat Sehat, Surat Keterangan Bebas Narkoba. - Kesehatan: Sehat jasmani & rohani, tidak buta warna, tidak mengidap penyakit menular, bebas narkoba - Kemampuan: Menguasai teknik mengemudi aman, responsif, tahu perawatan dasar kendaraan - Karakter: Jujur, sopan, ramah, disiplin waktu, bertanggung jawab, dan mampu menjaga kerahasiaan - Usia & Pengalaman: usia 24-45 tahun dan pengalaman kerja minimal 2 tahun - Kewarganegaraan: Indonesia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 3930);
