INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62181430', 62181430, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Belanja Pemeliharaan Irigasi', 'Barang', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 24940000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Pemeliharaan drainase jaringan air ( 172, M2, @ 145000 );', 'Pekerjaan ini mencakup perawatan rutin atau perbaikan ringan pada saluran pembuangan air di area kantor atau pelabuhan guna mencegah banjir dan genangan. Rincian spesifikasinya meliputi: Lingkup Pekerjaan: Pembersihan Sedimen: Pengerukan lumpur, pasir, dan sampah yang mengendap di dasar drainase yang menghambat laju air. Pembersihan Gulma: Pembabatan rumput liar atau tanaman yang tumbuh di sepanjang dinding dan bibir saluran. Perbaikan Ringan: Penambalan dinding drainase yang retak atau rusak menggunakan campuran semen dan pasir untuk mencegah rembesan. Pemeriksaan Grill/Tutup: Pembersihan dan pemeliharaan tutup drainase (jika ada) agar tidak tersumbat. Standar Hasil: Air dapat mengalir dengan lancar tanpa hambatan, tidak ada endapan sampah/lumpur yang menumpuk, dan kondisi fisik saluran kokoh. Pembuangan Limbah: Seluruh material hasil pengerukan (lumpur/sampah) harus diangkut dan dibuang ke tempat pembuangan akhir yang ditentukan, tidak boleh dibiarkan menumpuk di pinggir saluran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 5412);
