INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61662963', 61662963, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA RUMAH SUSUN VI', 'Penyediaan PJLP Petugas Keamanan UPRS VI', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 10874473415, 'November 2025', 'APBD', 1, 1, '155 Orang', '1.Mengawasi dan mengamankan aset-aset UPRS; 2.Melaksanakan pengawasan kepada warga dan pihak lain yang bukan penghuni rusun pada waktu masuk dan keluar area rusunawa; 3.Melakukan pengecekan barang-barang yang masuk dan keluar area rusunawa; 4.Melakukan pengawasan dan pengecekan barang bawaan para tamu yang mencurigakan; 5.Melakukan pencatatan kegiatan/kejadian selama melaksanakan tugas pengamanan di area rusunawa; 6.Monitoring unit-unit yang melakukan pelanggaran tata tertib hunian; 7.Menjaga keamanan/ketertiban di area rusunawa; 8.Mendampingi kegiatan penertiban unit usaha dan unit hunian; 9.Mengatur penempatan kendaraan pada tempat yang telah ditentukan di area rusunawa; 10.Monitoring seluruh area rusunawa unutk memastikan kondisi aman dan terkendali 11.Melaksanakan keamnaan dan ketertiban ruang kantor, aktivitas pelayanan, pos jaga dan sekitarnya; 12.Memantau keamanan melalui layar monitor cctv; 13.Mengamankan pelaksanaan acara atau event di area rusunawa; 14.Mendampingi KepalaUnit dan atau orang yang ditunjuk untuk melakukan pendataan dan atau inspeksi mendadak; 15.Mengambil langkah preventif atau represif dalam hal terjadi upaya dari pihak luar yang dapat mengganggu keamanan dan ketertiban dilingkungan rusunawa; 16.Melaksanakan tugas-tugas lain yang diberikan oleh Kepala UPRS; 17.Melaporkan dan mendokumentasikan hasil kegiatan monitoring.', '1.Mengawasi dan mengamankan aset-aset UPRS; 2.Melaksanakan pengawasan kepada warga dan pihak lain yang bukan penghuni rusun pada waktu masuk dan keluar area rusunawa; 3.Melakukan pengecekan barang-barang yang masuk dan keluar area rusunawa; 4.Melakukan pengawasan dan pengecekan barang bawaan para tamu yang mencurigakan; 5.Melakukan pencatatan kegiatan/kejadian selama melaksanakan tugas pengamanan di area rusunawa; 6.Monitoring unit-unit yang melakukan pelanggaran tata tertib hunian; 7.Menjaga keamanan/ketertiban di area rusunawa; 8.Mendampingi kegiatan penertiban unit usaha dan unit hunian; 9.Mengatur penempatan kendaraan pada tempat yang telah ditentukan di area rusunawa; 10.Monitoring seluruh area rusunawa unutk memastikan kondisi aman dan terkendali 11.Melaksanakan keamnaan dan ketertiban ruang kantor, aktivitas pelayanan, pos jaga dan sekitarnya; 12.Memantau keamanan melalui layar monitor cctv; 13.Mengamankan pelaksanaan acara atau event di area rusunawa; 14.Mendampingi KepalaUnit dan atau orang yang ditunjuk untuk melakukan pendataan dan atau inspeksi mendadak; 15.Mengambil langkah preventif atau represif dalam hal terjadi upaya dari pihak luar yang dapat mengganggu keamanan dan ketertiban dilingkungan rusunawa; 16.Melaksanakan tugas-tugas lain yang diberikan oleh Kepala UPRS; 17.Melaporkan dan mendokumentasikan hasil kegiatan monitoring.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 6007);
