INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123099', 62123099, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa Komunikasi Operasional UPT BMKG', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 29200000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Sewa komunikasi operasional UPT BMKG merupakan layanan penyediaan saluran komunikasi data dari Pusat BMKG ke UPT BMKG yang digunakan untuk mendukung kelancaran pengumpulan dan penyebaran data serta informasi meteorologi, klimatologi, dan geofisika. Layanan komunikasi ini menggunakan media Fiber Optik (FO) berbasis jaringan terestrial dengan sistem Virtual Private Network (VPN) guna menjamin keamanan, keandalan, dan integritas data yang dikirimkan. Jaringan komunikasi tersebut digunakan untuk mendukung operasional sistem informasi gempabumi dan tsunami, pemantauan Radar Cuaca, Analisis Parameter Cuaca (APC), sistem NDF (national digital forecast), pengelolaan cuaca maritim, serta pengelolaan dan distribusi data forecast yang berada di UPT BMKG, sekaligus mendukung pengiriman data gempabumi, data cuaca, data cuaca maritim, data cuaca penerbangan, data iklim, serta data perkantoran BMKG lainnya. Sistem komunikasi dirancang sebagai jaringan khusus (dedicated network) yang beroperasi secara kontinu selama 24 jam sehari dan 7 hari seminggu, sehingga mampu mendukung pengiriman data secara real-time dan berkelanjutan. Untuk menjamin kecepatan, kestabilan, dan keandalan penyebaran informasi, layanan sewa komunikasi data ini dilengkapi dengan sistem, prosedur, dan mekanisme operasional yang mencakup pengaturan jaringan, sistem pengiriman data, serta sarana pendukung komunikasi lainnya. Penyediaan layanan ini bertujuan untuk memastikan keberlanjutan serta peningkatan kinerja sistem pemantauan gempabumi dan tsunami, pemantauan Radar Cuaca, Radar Maritim, APC, Synergie, data iklim dan data forecast di seluruh UPT BMKG, tanpa mengganggu operasional layanan BMKG yang sedang berjalan.', 'Untuk mendukung kegiatan operasional kelangsungan pengiriman dan pertukaran data dan informasi secara tepat dan akurat dan tersedianya layanan jaringan komunikasi FO yang handal dengan SLA ≥99.5% /Bulan di 233 lokasi UPT BMKG, Radar cuaca maupun radar maritim. Kegiatan ini dilaksanakan selama 12 bulan, terhitung sejak 1 Januari 2026 sampai dengan 31 Desember 2026', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 6277);
