INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61684452', 61684452, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA RUMAH SUSUN II', 'Belanja Jasa Tenaga Pelayanan Umum (Petugas Pelayanan Umum - Customer Relation Officer)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 1062722700, 'December 2025', 'APBD', 1, 1, '12 Orang', 'Ruang Lingkup / batasan lingkup Pekerjaan Belanja Jasa Tenaga Pelayanan Umum (Petugas Pelayanan Umum - Customer Relation Officer) yaitu: 1. Menginformasikan dan mensosisalisasi peraturan penghunian Rumah Susun dan Program-program UPRS; 2. Menyampaikan himbauan pemenuhan kewajiban warga selaku wajib retribusi serta menyampaikan surat undangan, teguran dan peringatan kepada warga rusunawa; 3. Memberikan pembinaan kemasyarakatan kepada penghuni Rumah Susun; 4. Melaksanakan pengelolaan/operasional pelayanan berbasis Teknologi Informasi; 5. Melakukan identifikasi, pengelolaan dan pendataan warga Rumah Susun; 6. Melakukan analisa kebutuhan warga penghuni program pemberdayaan masyarakat dan pendampingan pelaksanaan program pemberdayaan dari SKPD/UKPD atau CSR; 7. Menerima, mengolah dan menindaklanjuti konsultasi/ keluhan/ pengaduan penghuni Rumah Susun; 8. Melaksanakan tugas-tugas lain yang diberikan oleh Kepala UPRS; 9. Melaporkan hasil pelaksanaan tugas kepada Ka. Subbagian Tata Usaha; 10. Melaporkan pelaksanaan tugas kepada Kepala Satuan Pelaksana Pelayanan UPRS; 11. Pendampingan hukum dalam menghadapi warga Rumah Susun, LSM dan Masyarakat; 12. Verifikasi data hasil pendebetan tagihan sewa Rumah Suusn melalui Bank DKI dan penagihan tunggakan per Unit Hunian; 13. Merekap hasil pendebetan tagihan sewa Rumah Susun berdasarkan per kode rekening penerima; 14. Penyetoran Penerimaan Retribusi dan Pendapatan Lain Daerah ke RKUD melalui Bank DKI; 15. Pelayanan, pengaduan, informasi dan konsultasi penghunian baik warga penghuni maupun non penghuni serta melaporkan ke DPRKP; 16. Penertiban hasil verifikasi data Badan Pajak dan Retribusi Daerah; 17. Pendataan warga dan Penertiban Hunian Rumah Susun; 18. Memberikan bimbingan psikologis kemasyarakat dan kesehatan bagi penghuni Rumah Susun; 19. Melakukan pendampingan program pemberdayaan dari SKPD/UKPD dan CSR.', 'Petugas Pelayanan Umum - Customer Relation Officer (PJLP Dinas Perumahan dan Kawasan Permukiman) Spesifikasi: Pendidikan Minimal D3 sederajat', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 6830);
