INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61747631', 61747631, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tenaga Ahli Pembangunan, Pengembangan dan Pengelolaan Aplikasi Cipta Karya, Tata Ruang dan Pertanahan (Tenaga Ahli Pengalaman Minimal 7 Tahun - Senior Software Developer) - 7', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 161700000, 'November 2025', 'APBD', 1, 1, '1 x 12 Bulan', '1. Menyusun dan menulis dokumentasi pengembangan program sebagai acuan dalam proses pengembangan, pemeliharaan, dan peningkatan sistem aplikasi. 2. Melakukan pengujian dan percobaan terhadap program atau aplikasi untuk memastikan bahwa hasil keluaran sesuai dengan spesifikasi dan kebutuhan pengguna. 3. Melakukan revisi, perbaikan, dan pengembangan program yang ada guna meningkatkan efisiensi, keandalan, serta kinerja sistem. 4. Menganalisis dan meninjau struktur program, serta menulis ulang atau menyempurnakan kode dengan menggunakan diagram alur kerja, logika simbolik, dan prinsip pemrograman yang efisien. 5. Berkolaborasi dan berkonsultasi dengan tim pengembang atau tenaga ahli lainnya untuk mengidentifikasi permasalahan teknis dan menentukan solusi yang tepat. 6. Melaksanakan analisis sistem dan pemrograman teknis untuk memelihara, mengontrol, serta mengoptimalkan penggunaan perangkat lunak dan sistem komputer. 7. Melaksanakan tugas lain yang ditetapkan oleh pimpinan atau atasan sesuai dengan kewenangan dan tanggung jawab jabatan.', 'a. S1/D4 Teknik Komputer / Teknik Informatika / Sistem Informasi / Geografi / Teknik Elektro / Teknik Geomatika / Teknik Geografi atau Program Studi Sejenis; b. Memiliki pengalaman 7 Tahun dalam bidang IT atau pengalaman sejenis; c. Memiliki NIB dengan KBLI 62019. d.Mampu mencari akar masalah dengan pendekatan yang sistematis (troubleshooting dengan pendekatan root cause analysis); e.Mampu menganalisis kebutuhan serta merancang dan mengembangkan sistem aplikasi sesuai standar teknis dan kebutuhan bisnis; f. Menguasai bahasa pemrograman PHP (minimal versi 5), HTML, JavaScript, Java, jQuery, CSS, dan framework terkait; g. Menguasai konsep arsitektur aplikasi seperti MVC dan HMVC, serta framework modern berbasis PHP dan JavaScript; h. Menguasai pengelolaan dan optimasi database PostgreSQL, MySQL, dan Oracle (menjadi nilai tambah); i. Memiliki pengalaman dalam mengelola dan mengoptimalkan web server seperti Apache dan Nginx, serta integrasi API Web Service/Map Service (JSON, GeoJSON, REST, dll.); j. Mampu menyusun dan menganalisis alur kerja bisnis proses (business process flow) untuk mendukung pengembangan sistem; k. Mampu menjelaskan aspek teknis secara sistematis, mudah dipahami, serta memberikan rekomendasi konkret dari hasil analisis dan visualisasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 7926);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62648069', 62648069, 'analyze_legacy', 'Kab. Gresik', 'kabkota', 'BAGIAN UMUM', 'Penyediaan Bahan/Material', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Gresik (Kab.)', 593400000, 'January 2026', 'APBD', 1, 1, '20 Paket', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Suvenir/Cendera Mata; B.1.SSH.2986-Kue Tart; B.1.SSH.2987-Makanan khas gresik; B.1.SSH.2977-Emas; B.1.SSH.2978-Gelas Mug; B.1.SSH.2989-Mukena; B.1.SSH.2991-parcel buah; B.1.SSH.2984-kue kering; B.1.SSH.2983-kosmetik; B.1.SSH.2999-suvenir perabot rumah tangga; B.1.SSH.2995-Sarung; B.1.SSH.3016-Kain Batik Motif Khas Gresik; B.1.SSH.2993-Sajadah; B.1.SSH.3001-Tumpeng; B.1.SSH.2985-Kue Kering Toples; B.1.SSH.2980-kain batik; B.1.SSH.2981-kain batik; B.1.SSH.2982-Karangan Bunga; B.1.SSH.2998-suvenir perabot rumah tangga; B.1.SSH.2997-Souvenir Tas; B.1.SSH.2996-sepatu;', 'jeruk, anggur, kelengkeng, salak, manggis dll; Kue Ulang Tahun; Uk. Besar; paket (isi bandeng, pudak, kerupuk, cubung, ayas, dll); 1 Gram; 450 ml; premium; parcel premium; premium; bahan plastik; ; Bahan Katun sutra; Premium 100x150; Nasi Tumpeng VIP; ; khas gresik; premium; karangan bunga papan; bahan kaca; bahan kulit premium; premium;', 593400000, 'absurd', 'Pengadaan suvenir/cendera mata untuk kegiatan kantor memuat banyak barang konsumtif dan hadiah seperti emas 1 gram, kosmetik, mukena, sarung, sajadah, sepatu, parcel premium, kue tart, tumpeng VIP, dan perabot rumah tangga. Dalam konteks belanja bahan kantor pada Bagian Umum, komposisi ini sangat tidak selaras dengan kebutuhan operasional pemerintahan dan menimbulkan kesan penggunaan APBD untuk bingkisan/hadiah yang tidak patut.', NULL, NULL, 4, 1, 1, 1, 1, 7927);
