INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61646501', 61646501, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BADAN KEPEGAWAIAN DAERAH', 'Belanja Jasa Surveillance ISO', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 95956793, 'August 2026', 'APBD', 1, 1, '1 (kegiatan) x 2 (bulan)', 'Persiapan Surveillance - Menyusun rencana pelaksanaan surveillance SMKI (jadwal, scope, unit yang diaudit). - Mengkoordinasikan ketersediaan dokumen dan eviden pendukung dengan unit terkait. - Mengupdate risiko dan konteks organisasi terkait keamanan informasi. Pelaksanaan Surveillance - Mengumpulkan dan memverifikasi bukti penerapan kontrol keamanan informasi. - Melakukan wawancara, observasi, dan telaah dokumen dengan pemilik proses. - Memastikan pengendalian keamanan informasi dijalankan sesuai prosedur, instruksi kerja, dan kebijakan. Evaluasi dan Analisis - Mengidentifikasi ketidaksesuaian (non-conformity), temuan observasi, dan area peningkatan (opportunity for improvement). - Membandingkan tingkat kepatuhan dengan persyaratan ISO/IEC 27001:2022. - Menilai efektivitas kontrol keamanan informasi yang telah diterapkan. Pelaporan Hasil Surveillance - Menyusun dan menyampaikan laporan hasil surveillance kepada pimpinan. - Memberikan rekomendasi tindakan korektif dan preventive secara sistematis. - Melakukan tindak lanjut pemantauan terhadap pelaksanaan perbaikan temuan.', 'Dalam rangka Pelaksanaan Surveillance ke-2 SMKI ISO 270001:2022', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 8370);
