INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61805510', 61805510, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT HIGIENE PERUSAHAAN, KESELAMATAN DAN KESEHATAN KERJA', 'Belanja Jasa Tenaga Laboratorium', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1023373022, 'December 2025', 'APBD', 1, 1, '14 Orang', 'a. Melaksanakan pengambilan sampel lingkungan kerja; b. Melaksanakan analisis sampel udara lingkungan kerja; c. Melaksanakan persiapan alat dan bahan lingkungan kerja; d. Melakukan kalibrasi, pengecekan dan perawatan peralatan laboratorium lingkungan kerja; e. Melakukan pencatatan, perhitungan dan administrasi lingkungan kerja. f. Melaksanakan persiapan peralatan kesehatan kerja; g. Melaksanakan pemeriksaan kesehatan kerja di bawah supervisi Dokter Kesehatan Kerja; h. Melakukan analisa hasil pemeriksaan kesehatan kerja di bawah supervisi Dokter Kesehatan Kerja; i. Melakukan persiapan dan pelaksanaan pelatihan; j. Melakukan pendampingan kunjungan lapangan yang berkaitan dengan pelatihan; k. Melakukan pembuatan laporan hasil pemeriksaan kesehatan kerja dan laporan pelatihan.', 'Persyaratan kualifikasi administrasi/ legalitas meliputi: 1. Memenuhi ketentuan peraturan perundang-undangan untuk menjalankan kegiatan/usaha. 2. Memiliki identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP/Paspor/Surat Keterangan Domisili Tinggal); 3. Memiliki status valid keterangan Wajib Pajak berdasarkan hasil konfirmasi status Wajib Pajak; 4. Surat Pernyataan Pakta Integritas. 5. Surat pernyataan yang ditandatangani Peserta yang berisi: • Tidak dikenakan Sanksi Daftar Hitam; • Keikutsertaannya tidak menimbulkan pertentangan kepentingan pihak yang terkait; • Tidak dalam pengawasan pengadilan dan/atau sedang menjalani sanksi pidana; dan • Tidak berstatus Aparatur Sipil Negara, kecuali yang bersangkutan mengambil cuti di luar tanggungan Negara. b. Persyaratan Kualifikasi Teknis Peserta Persyaratan kualifikasi teknis meliputi: 1. Berusia minimal 18 (delapan belas) tahun dan maksimal 56 (lima puluh enam) tahun 0 bulan 0 hari pada tanggal 1 Januari 2025; 2. Berkelakukan baik dan tidak pernah dihukum penjara atau kurungan berdasarkan putusan pengadilan yang telah mempunyai kekuatan hukum tetap karena melakukan suatu tindak pidana kejahatan (dibuktikan dengan fotokopi SKCK yang masih berlaku); 3. Sehat jasmani, rohani/mental dan tidak memiliki kelainan yang dapat mengganggu pelaksanaan pekerjaan (dibuktikan dengan Fotokopi Surat Keterangan Kesehatan dari dokter pemerintah) ; 4. Pendidikan minimal SLTA dengan pengalaman kerja dibidang Laboran; 5. Tidak bertato atau bekas tato dan tidak ditindik atau bekas tindik telinga atau anggota tubuh lainnya; 6. Bebas Narkoba dibuktikan dengan fotokopi surat keterangan bebas narkoba dari RS Pemerintah / BNN (Badan Narkotika Nasional) / Laboratorium Kesehatan Pemerintah yang masih berlaku; 7. Pelamar menandatangani surat pernyataan bermaterai Rp 10.000,- bahwa : • Tidak menuntut untuk diangkat menjadi CPNS/PNS atau Pegawai Pemerintah dengan Perjanjian Kerja (PPPK); • Tidak pernah diberhentikan dengan tidak hormat sebagai pegawai/karyawan pada perusahaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 9220);
