INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62898393', 62898393, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pengadaan Water Barrier', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 16810000, 'January 2026', 'APBD', 1, 1, '10 Unit', 'Uraian pekerjaan Pengadaan Road Barrier Tenaga ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan road barrier / water barrier jenis tenaga (portable/manual) yang digunakan untuk mendukung pengaturan lalu lintas, pengamanan area kerja, penutupan sementara jalan, serta pengendalian arus kendaraan pada kegiatan operasional, konstruksi, atau kegiatan insidentil lainnya. Pekerjaan ini mencakup penyediaan road barrier tenaga yang memenuhi spesifikasi teknis, memiliki konstruksi kuat, stabil, mudah dipindahkan secara manual, serta aman digunakan di area publik. Road barrier yang disediakan harus mampu berfungsi sebagai pembatas fisik yang jelas, terlihat, dan efektif dalam mengarahkan atau membatasi pergerakan kendaraan dan pejalan kaki.', '1.Tipe Road barrier tenaga/manual (portable) Dioperasikan tanpa sistem listrik atau hidrolik 2. Bahan Plastik HDPE / PVC tebal atau material setara berkekuatan tinggi Tahan terhadap benturan ringan, cuaca, dan sinar UV 3. Dimensi Panjang: ± 1.000 – 1.500 mm Tinggi: ± 800 – 1.000 mm Lebar dasar: ± 400 – 600 mm 4. Warna Merah, oranye, atau kombinasi merah–putih Warna mencolok dan mudah terlihat 5. Reflektor Dilengkapi strip reflektif atau stiker reflektor Terlihat jelas pada malam hari atau kondisi minim cahaya 6. Sistem Penahan Dapat diisi air atau pasir untuk menambah berat dan stabilitas Memiliki lubang pengisian dan penutup yang aman 7. Konektivitas Dapat disambung antar unit (interlocking system) Meningkatkan stabilitas dan panjang pembatas 8. Karakteristik Teknis Mudah dipindahkan secara manual Stabil saat digunakan di permukaan jalan Tidak tajam dan aman bagi pengguna jalan Tidak mudah terguling saat terisi 9. Kondisi Barang Baru (bukan bekas/rekondisi) Tidak retak, bocor, atau cacat produksi 10. Standar Mutu Memenuhi standar keselamatan perlengkapan lalu lintas Setara dengan produk yang umum digunakan pada pengamanan jalan 11. Jumlah Sesuai kebutuhan dan tercantum dalam kontrak atau surat pesanan 12. Pengemasan dan Pengiriman Dikemas rapi dan aman Pengiriman ke lokasi sesuai penetapan PPK/Pejabat Pengadaan 13. Pemeriksaan dan Serah Terima Diperiksa oleh Pejabat Pembuat Komitmen Serah terima dibuktikan dengan Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 9837);
